174	#[derive(Clone, Debug, Eq, PartialEq)]
175	pub(crate) struct KimiRankWeightNames {
176	    pub rank: usize,
177	    pub plan: KimiRankWeightPlan,
178	    pub top: KimiTopWeightNames,
179	    pub layers: Vec<KimiLayerWeightNames>,
180	}
181	
182	impl KimiK2WeightManifest {
183	    pub(crate) fn from_model_dir(model_path: &Path) -> Result<Self> {
184	        Self::from_index_file(&model_path.join(KIMI_K2_WEIGHT_INDEX))
185	    }
186	
187	    fn from_index_file(index_path: &Path) -> Result<Self> {
188	        let content = std::fs::read_to_string(index_path)
189	            .with_context(|| format!("failed to read {}", index_path.display()))?;
190	        let json: Value = serde_json::from_str(&content)
191	            .with_context(|| format!("failed to parse {}", index_path.display()))?;
192	        Self::from_index_json(&json)
193	    }
194	
195	    pub(crate) fn from_index_json(json: &Value) -> Result<Self> {
196	        let weight_map = json
197	            .get("weight_map")
198	            .and_then(Value::as_object)
199	            .ok_or_else(|| anyhow::anyhow!("Kimi safetensors index missing weight_map"))?;
200	        let mut tensors = BTreeMap::new();
201	        for (name, shard) in weight_map {
202	            let shard = shard
203	                .as_str()
204	                .ok_or_else(|| anyhow::anyhow!("weight_map entry {name} is not a shard string"))?;
205	            tensors.insert(name.as_str(), shard);
206	        }
207	
208	        let token_embedding = tensor(&tensors, "language_model.model.embed_tokens.weight")?;
209	        let final_norm = tensor(&tensors, "language_model.model.norm.weight")?;
210	        let lm_head = tensor(&tensors, "language_model.lm_head.weight")?;
211	        let mut layers = Vec::with_capacity(KIMI_K2_LAYERS);
212	        for layer_idx in 0..KIMI_K2_LAYERS {
213	            let attention = attention_manifest(&tensors, layer_idx)?;
214	            let kind = if layer_idx < KIMI_K2_DENSE_LAYERS {
215	                KimiLayerKindManifest::Dense(dense_mlp_manifest(&tensors, layer_idx)?)
216	            } else {
217	                KimiLayerKindManifest::Moe(moe_layer_manifest(&tensors, layer_idx)?)
218	            };
219	            layers.push(KimiLayerManifest {
220	                layer_idx,
221	                attention,
222	                kind,
223	            });
224	        }
225	
226	        let manifest = Self {
227	            text_tensor_count: weight_map
228	                .keys()
229	                .filter(|name| name.starts_with(TEXT_PREFIX))
230	                .count(),
231	            token_embedding,
232	            final_norm,
233	            lm_head,
234	            layers,
235	            parallel: KimiK2ParallelShape::tp8_ep8(),
236	        };
237	        manifest.validate()?;
238	        Ok(manifest)
239	    }
240	
241	    pub(crate) fn with_parallel_shape(mut self, shape: KimiK2ParallelShape) -> Result<Self> {
242	        self.parallel = shape;
243	        self.validate()?;
244	        Ok(self)
245	    }
246	
247	    fn validate(&self) -> Result<()> {
248	        ensure!(
249	            self.layers.len() == KIMI_K2_LAYERS,
250	            "Kimi manifest expected {KIMI_K2_LAYERS} layers, got {}",
251	            self.layers.len()
252	        );
253	        let moe_layers = self
254	            .layers
255	            .iter()
256	            .filter(|layer| matches!(layer.kind, KimiLayerKindManifest::Moe(_)))
257	            .count();
258	        ensure!(
259	            moe_layers == KIMI_K2_MOE_LAYERS,
260	            "Kimi manifest expected {KIMI_K2_MOE_LAYERS} MoE layers, got {moe_layers}"
261	        );
262	        ensure!(
263	            self.parallel.ep_world > 0
264	                && KIMI_K2_ROUTED_EXPERTS.is_multiple_of(self.parallel.ep_world)
265	                && crate::config::KIMI_K2_HEADS.is_multiple_of(self.parallel.tp_world)
266	                && crate::config::KIMI_K2_VOCAB.is_multiple_of(self.parallel.tp_world),
267	            "Kimi parallel shape TP{}/DP{}/EP{} does not evenly divide model dimensions",
268	            self.parallel.tp_world,
269	            self.parallel.dp_world,
270	            self.parallel.ep_world
271	        );
272	        Ok(())
273	    }
274	
275	    fn rank_plan(&self, rank: usize) -> Result<KimiRankWeightPlan> {
276	        ensure!(
277	            rank < self.parallel.ep_world,
278	            "Kimi rank {rank} outside EP{}",
279	            self.parallel.ep_world
280	        );
281	        let parallel = self.parallel.parallel_config();
282	        let tp_rank = parallel.tp_rank(rank);
283	        let ep_rank = parallel.ep_rank(rank);
284	        let attention_head_range =
285	            tp_rank * self.parallel.heads_per_tp..(tp_rank + 1) * self.parallel.heads_per_tp;
286	        let vocab_range =
287	            tp_rank * self.parallel.vocab_per_tp..(tp_rank + 1) * self.parallel.vocab_per_tp;
288	        let local_expert_range =
289	            ep_rank * self.parallel.local_experts..(ep_rank + 1) * self.parallel.local_experts;
290	        let names = self.rank_tensor_names(rank)?;
291	        Ok(KimiRankWeightPlan {
292	            tp_rank,
293	            ep_rank,
294	            attention_head_range,
295	            vocab_range,
296	            local_expert_range,
297	            tensor_count: names.len(),
298	        })
299	    }
300	
301	    pub(crate) fn rank_tensor_names(&self, rank: usize) -> Result<Vec<&KimiTensorEntry>> {
302	        let local_expert_range = self.rank_local_expert_range(rank)?;
303	        let mut names = Vec::new();
304	        names.push(&self.token_embedding);
305	        names.push(&self.final_norm);
306	        names.push(&self.lm_head);
307	        for layer in &self.layers {
308	            push_attention(&mut names, &layer.attention);
309	            match &layer.kind {
310	                KimiLayerKindManifest::Dense(mlp) => push_dense_mlp(&mut names, mlp),
311	                KimiLayerKindManifest::Moe(moe) => {
312	                    names.push(&moe.router.gate_weight);
313	                    names.push(&moe.router.e_score_correction_bias);
314	                    names.push(&moe.shared_experts.gate_proj);
315	                    names.push(&moe.shared_experts.up_proj);
316	                    names.push(&moe.shared_experts.down_proj);
317	                    for expert in &moe.routed_experts {
318	                        if local_expert_range.contains(&expert.expert_idx) {
319	                            push_int4_projection(&mut names, &expert.gate_proj);
320	                            push_int4_projection(&mut names, &expert.up_proj);
321	                            push_int4_projection(&mut names, &expert.down_proj);
322	                        }
323	                    }
324	                }
325	            }
326	        }
327	        Ok(names)
328	    }
329	
330	    pub(crate) fn rank_sliced_load_plan(&self, rank: usize) -> Result<KimiRankSlicedLoadPlan> {
331	        let entries = self.rank_tensor_load_specs(rank)?;
332	        let mut by_shard: BTreeMap<String, Vec<KimiTensorLoadSpec>> = BTreeMap::new();
333	        for entry in entries {
334	            by_shard.entry(entry.shard.clone()).or_default().push(entry);
335	        }
336	        let tensor_count = by_shard.values().map(Vec::len).sum();
337	        let shards = by_shard
338	            .into_iter()
339	            .map(|(shard, tensors)| KimiShardTensorLoadPlan { shard, tensors })
340	            .collect();
341	        Ok(KimiRankSlicedLoadPlan {
342	            rank,
343	            shards,
344	            tensor_count,
345	        })
346	    }
347	
348	    fn rank_tensor_load_specs(&self, rank: usize) -> Result<Vec<KimiTensorLoadSpec>> {
349	        let plan = self.rank_plan(rank)?;
350	        let local_expert_range = self.rank_local_expert_range(rank)?;
351	        let mut specs = Vec::with_capacity(plan.tensor_count);
352	        let vocab_rows = KimiTensorLoadSlice::RowRange {
353	            start: plan.vocab_range.start,
354	            end: plan.vocab_range.end,
355	        };
356	        push_load_spec(&mut specs, &self.token_embedding, vocab_rows.clone());
357	        push_load_spec(&mut specs, &self.final_norm, KimiTensorLoadSlice::Full);
358	        push_load_spec(&mut specs, &self.lm_head, vocab_rows);
359	
360	        for layer in &self.layers {
361	            push_attention_load_specs(&mut specs, &layer.attention, &plan);
362	            match &layer.kind {
363	                KimiLayerKindManifest::Dense(mlp) => {
364	                    let rows = rank_shard_rows(
365	                        KIMI_K2_DENSE_INTERMEDIATE,
366	                        plan.tp_rank,
367	                        self.parallel.tp_world,
368	                    );
369	                    push_load_spec(&mut specs, &mlp.gate_proj, rows.clone());
370	                    push_load_spec(&mut specs, &mlp.up_proj, rows.clone());
371	                    push_load_spec(&mut specs, &mlp.down_proj, row_slice_to_col_slice(rows));
372	                }
373	                KimiLayerKindManifest::Moe(moe) => {
374	                    push_load_spec(
375	                        &mut specs,
376	                        &moe.router.gate_weight,
377	                        KimiTensorLoadSlice::Full,
378	                    );
379	                    push_load_spec(
380	                        &mut specs,
381	                        &moe.router.e_score_correction_bias,
382	                        KimiTensorLoadSlice::Full,
383	                    );
384	                    let shared_rows = rank_shard_rows(
385	                        KIMI_K2_EXPERT_INTERMEDIATE,
386	                        plan.tp_rank,
387	                        self.parallel.tp_world,
388	                    );
389	                    push_load_spec(
390	                        &mut specs,
391	                        &moe.shared_experts.gate_proj,
392	                        shared_rows.clone(),
393	                    );
394	                    push_load_spec(&mut specs, &moe.shared_experts.up_proj, shared_rows.clone());
395	                    push_load_spec(
396	                        &mut specs,
397	                        &moe.shared_experts.down_proj,
398	                        row_slice_to_col_slice(shared_rows),
399	                    );
400	                    for expert in &moe.routed_experts {
401	                        if local_expert_range.contains(&expert.expert_idx) {
402	                            push_int4_projection_load_specs(&mut specs, &expert.gate_proj);
403	                            push_int4_projection_load_specs(&mut specs, &expert.up_proj);
404	                            push_int4_projection_load_specs(&mut specs, &expert.down_proj);
405	                        }
406	                    }
407	                }
408	            }
409	        }
410	
411	        let unique = specs
412	            .iter()
413	            .map(|spec| spec.name.as_str())
414	            .collect::<BTreeSet<_>>();
415	        ensure!(
416	            unique.len() == specs.len(),
417	            "Kimi rank {rank} sliced load plan contains duplicate tensors"
418	        );
419	        ensure!(
420	            specs.len() == plan.tensor_count,
421	            "Kimi rank {rank} sliced load count {} does not match tensor plan {}",
422	            specs.len(),
423	            plan.tensor_count
424	        );
425	        Ok(specs)
426	    }
427	
428	    pub(crate) fn rank_weight_names(&self, rank: usize) -> Result<KimiRankWeightNames> {
429	        let plan = self.rank_plan(rank)?;
430	        let local_expert_range = self.rank_local_expert_range(rank)?;
431	        let top = KimiTopWeightNames {
432	            token_embedding: self.token_embedding.name.clone(),
433	            final_norm: self.final_norm.name.clone(),
434	            lm_head: self.lm_head.name.clone(),
435	        };
436	        let mut layers = Vec::with_capacity(self.layers.len());
437	        for layer in &self.layers {
438	            let attention = KimiAttentionWeightNames::from_manifest(&layer.attention);
439	            let kind = match &layer.kind {
440	                KimiLayerKindManifest::Dense(mlp) => {
441	                    KimiLayerWeightKindNames::Dense(KimiDenseMlpWeightNames::from_manifest(mlp))
442	                }
443	                KimiLayerKindManifest::Moe(moe) => {
444	                    let routed_experts = moe
445	                        .routed_experts
446	                        .iter()
447	                        .filter(|expert| local_expert_range.contains(&expert.expert_idx))
448	                        .map(KimiRoutedExpertWeightNames::from_manifest)
449	                        .collect();
450	                    KimiLayerWeightKindNames::Moe(KimiMoeLayerWeightNames {
451	                        router: KimiRouterWeightNames {
452	                            gate_weight: moe.router.gate_weight.name.clone(),
453	                            e_score_correction_bias: moe
454	                                .router
455	                                .e_score_correction_bias
456	                                .name
457	                                .clone(),
458	                        },
459	                        shared_experts: KimiSharedExpertWeightNames {
460	                            gate_proj: moe.shared_experts.gate_proj.name.clone(),
461	                            up_proj: moe.shared_experts.up_proj.name.clone(),
462	                            down_proj: moe.shared_experts.down_proj.name.clone(),
463	                        },
464	                        routed_experts,
465	                    })
466	                }
467	            };
468	            layers.push(KimiLayerWeightNames {
469	                layer_idx: layer.layer_idx,
470	                attention,
471	                kind,
472	            });
473	        }
474	        Ok(KimiRankWeightNames {
475	            rank,
476	            plan,
477	            top,
478	            layers,
479	        })
480	    }
481	
482	    fn rank_local_expert_range(&self, rank: usize) -> Result<Range<usize>> {
483	        let ep_rank = self.parallel.parallel_config().ep_rank(rank);
484	        ensure!(
485	            ep_rank < self.parallel.ep_world,
486	            "Kimi EP rank {ep_rank} outside EP{}",
487	            self.parallel.ep_world
488	        );
489	        Ok(ep_rank * self.parallel.local_experts..(ep_rank + 1) * self.parallel.local_experts)
490	    }
491	}
