605	fn rank_shard_rows(total_rows: usize, rank: usize, world: usize) -> KimiTensorLoadSlice {
606	    debug_assert_eq!(total_rows % world, 0);
607	    let rows_per_rank = total_rows / world;
608	    KimiTensorLoadSlice::RowRange {
609	        start: rank * rows_per_rank,
610	        end: (rank + 1) * rows_per_rank,
611	    }
612	}
