#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct KimiMoeLayerManifest {
    pub router: KimiRouterManifest,
    pub shared_experts: KimiSharedExpertManifest,
    pub routed_experts: Vec<KimiRoutedExpertManifest>,
