12	impl KimiTensorLoadSlice {
13	    fn local_shape(&self, full_shape: &[usize]) -> Result<Vec<usize>> {
14	        match *self {
15	            Self::Full => Ok(full_shape.to_vec()),
16	            Self::RowRange { start, end } => {
17	                ensure!(
18	                    full_shape.len() == 2 && start <= end && end <= full_shape[0],
19	                    "Kimi row slice [{start}..{end}) is invalid for shape {:?}",
20	                    full_shape
21	                );
22	                Ok(vec![end - start, full_shape[1]])
23	            }
24	            Self::ColRange { start, end } => {
25	                ensure!(
26	                    full_shape.len() == 2 && start <= end && end <= full_shape[1],
27	                    "Kimi col slice [{start}..{end}) is invalid for shape {:?}",
28	                    full_shape
29	                );
30	                Ok(vec![full_shape[0], end - start])
31	            }
32	        }
33	    }
34	
35	    fn local_bytes(&self, full_shape: &[usize], dtype: Dtype) -> Result<usize> {
36	        Ok(self.local_shape(full_shape)?.iter().product::<usize>() * dtype_element_bytes(dtype)?)
37	    }
38	}
