75	pub(crate) fn load_rank_sliced_weights_to_gpu(
76	    ctx: &KimiRankGpuContext,
77	    model_path: &Path,
78	    load_plan: &KimiRankSlicedLoadPlan,
79	    names: &KimiRankWeightNames,
80	) -> Result<KimiRankSlicedLoadOutput> {
81	    ctx.set_current()?;
82	    ensure!(
83	        load_plan.rank == names.rank,
84	        "Kimi rank sliced load plan {} does not match typed names rank {}",
85	        load_plan.rank,
86	        names.rank
87	    );
88	    let mut weights = KimiRankGpuWeights {
89	        rank: load_plan.rank,
90	        tensors: BTreeMap::new(),
91	        total_bytes: 0,
92	    };
93	    let mut loaded_tensor_count = 0usize;
94	    let mut loaded_total_bytes = 0usize;
95	    let mut packed_moe_layers = BTreeSet::new();
96	    let mut expert_layers = Vec::with_capacity(KIMI_K2_MOE_LAYERS);
97	    let load_started = Instant::now();
98	    debug!(
99	        "rank {} start weight load: tensors={}, shards={}",
100	        load_plan.rank,
101	        load_plan.tensor_count,
102	        load_plan.shards.len()
103	    );
104	    let mut slowest_shard: Option<(String, f64)> = None;
105	    for shard in &load_plan.shards {
106	        let path = model_path.join(&shard.shard);
107	        let shard_started = Instant::now();
108	        let mmap = mmap_file(&path)?;
109	        let safetensors = SafeTensors::deserialize(&mmap)
110	            .with_context(|| format!("failed to deserialize {}", path.display()))?;
111	        for spec in &shard.tensors {
112	            let view = safetensors
113	                .tensor(&spec.name)
114	                .with_context(|| format!("missing tensor {} in {}", spec.name, path.display()))?;
115	            let shape = spec.slice.local_shape(view.shape())?;
116	            let bytes = spec.slice.local_bytes(view.shape(), view.dtype())?;
117	            let data = if spec.slice == KimiTensorLoadSlice::Full {
118	                ctx.stream()
119	                    .clone_htod(view.data())
120	                    .with_context(|| format!("failed to copy Kimi tensor {} to GPU", spec.name))?
121	            } else {
122	                let sliced =
123	                    sliced_tensor_bytes(view.data(), view.shape(), view.dtype(), &spec.slice)
124	                        .with_context(|| format!("failed to slice Kimi tensor {}", spec.name))?;
125	                ctx.stream()
126	                    .clone_htod(sliced.as_slice())
127	                    .with_context(|| format!("failed to copy Kimi tensor {} to GPU", spec.name))?
128	            };
129	            let tensor = KimiGpuRawTensor {
130	                name: spec.name.clone(),
131	                dtype: view.dtype(),
132	                shape,
133	                bytes,
134	                data,
135	            };
136	            weights.total_bytes += tensor.bytes;
137	            loaded_total_bytes += tensor.bytes;
138	            loaded_tensor_count += 1;
139	            ensure!(
140	                weights.tensors.insert(spec.name.clone(), tensor).is_none(),
141	                "duplicate Kimi tensor {} in rank {} sliced load plan",
142	                spec.name,
143	                load_plan.rank
144	            );
145	        }
146	        weights.pack_loaded_expert_marlin_layers(
147	            ctx,
148	            names,
149	            &mut packed_moe_layers,
150	            &mut expert_layers,
151	        )?;
152	        let shard_secs = shard_started.elapsed().as_secs_f64();
153	        match &slowest_shard {
154	            Some((_, slowest_secs)) if *slowest_secs >= shard_secs => {}
155	            _ => slowest_shard = Some((shard.shard.clone(), shard_secs)),
156	        }
157	    }
158	    ensure!(
159	        loaded_tensor_count == load_plan.tensor_count,
160	        "Kimi rank {} sliced GPU tensor count {} does not match load plan {}",
161	        load_plan.rank,
162	        loaded_tensor_count,
163	        load_plan.tensor_count
164	    );
165	    ensure!(
166	        expert_layers.len() == KIMI_K2_MOE_LAYERS,
167	        "Kimi rank {} expected {KIMI_K2_MOE_LAYERS} streamed MoE Marlin weight layers, got {}",
168	        load_plan.rank,
169	        expert_layers.len()
170	    );
171	    weights.validate_non_expert_typed_view(names)?;
172	    let expert_kernel_total_bytes = expert_layers.iter().map(|layer| layer.total_bytes).sum();
173	    let expert_kernel_weights = KimiRankExpertMarlinWeights {
174	        rank: load_plan.rank,
175	        local_expert_range: names.plan.local_expert_range.clone(),
176	        layers: expert_layers,
177	        total_bytes: expert_kernel_total_bytes,
178	    };
179	    debug!("rank {} start weight copy sync", load_plan.rank);
180	    let sync_started = Instant::now();
181	    ctx.sync().with_context(|| {
182	        format!(
183	            "failed to finish Kimi rank {} sliced GPU tensor copies",
184	            load_plan.rank
185	        )
186	    })?;
187	    debug!(
188	        "rank {} weight copy sync cost {:.2}s",
189	        load_plan.rank,
190	        sync_started.elapsed().as_secs_f64()
191	    );
192	    let (slowest_shard, slowest_secs) = slowest_shard.unwrap_or_else(|| ("none".to_owned(), 0.0));
193	    debug!(
194	        "rank {} weight load cost {:.2}s: loaded_tensors={}, loaded_bytes={}, resident_raw_bytes={}, expert_package_bytes={}, packed_moe_layers={}, slowest_shard={} {:.2}s",
195	        load_plan.rank,
196	        load_started.elapsed().as_secs_f64(),
197	        loaded_tensor_count,
198	        ByteSize(loaded_total_bytes as u64),
199	        ByteSize(weights.total_bytes as u64),
200	        ByteSize(expert_kernel_weights.total_bytes as u64),
201	        packed_moe_layers.len(),
202	        slowest_shard,
203	        slowest_secs
204	    );
205	    Ok(KimiRankSlicedLoadOutput {
206	        weights,
207	        expert_kernel_weights,
208	        loaded_tensor_count,
209	        loaded_total_bytes,
210	    })
211	}
212	
213	pub(super) fn sliced_tensor_bytes(
214	    data: &[u8],
215	    shape: &[usize],
216	    dtype: Dtype,
217	    slice: &KimiTensorLoadSlice,
218	) -> Result<Vec<u8>> {
219	    let element_bytes = dtype_element_bytes(dtype)?;
220	    match *slice {
221	        KimiTensorLoadSlice::Full => Ok(data.to_vec()),
222	        KimiTensorLoadSlice::RowRange { start, end } => {
223	            ensure!(
224	                shape.len() == 2 && start <= end && end <= shape[0],
225	                "invalid row slice [{start}..{end}) for shape {:?}",
226	                shape
227	            );
228	            let row_bytes = shape[1] * element_bytes;
229	            let start_byte = start * row_bytes;
230	            let end_byte = end * row_bytes;
231	            ensure!(
232	                end_byte <= data.len(),
233	                "row slice byte range [{start_byte}..{end_byte}) exceeds tensor bytes {}",
234	                data.len()
235	            );
236	            Ok(data[start_byte..end_byte].to_vec())
237	        }
238	        KimiTensorLoadSlice::ColRange { start, end } => {
239	            ensure!(
240	                shape.len() == 2 && start <= end && end <= shape[1],
241	                "invalid col slice [{start}..{end}) for shape {:?}",
242	                shape
243	            );
244	            let rows = shape[0];
245	            let cols = shape[1];
246	            let row_bytes = cols * element_bytes;
247	            let local_cols = end - start;
248	            let local_row_bytes = local_cols * element_bytes;
249	            let mut out = vec![0u8; rows * local_row_bytes];
250	            for row in 0..rows {
251	                let src = row * row_bytes + start * element_bytes;
252	                let dst = row * local_row_bytes;
253	                out[dst..dst + local_row_bytes].copy_from_slice(&data[src..src + local_row_bytes]);
254	            }
255	            Ok(out)
256	        }
257	    }
258	}
259	
260	fn mmap_file(path: &Path) -> Result<Mmap> {
261	    let file =
262	        fs::File::open(path).with_context(|| format!("failed to open {}", path.display()))?;
263	    // SAFETY: checkpoint shards are opened read-only and the mapping is only
264	    // consumed while reading safetensors metadata or copying tensor bytes.
265	    unsafe { Mmap::map(&file) }.with_context(|| format!("failed to mmap {}", path.display()))
266	}
267	
268	pub(super) fn dtype_element_bytes(dtype: Dtype) -> Result<usize> {
269	    match dtype {
270	        Dtype::BF16 => Ok(2),
271	        Dtype::F32 | Dtype::I32 => Ok(4),
272	        Dtype::U8 => Ok(1),
273	        other => bail!("Kimi loader does not support dtype {:?}", other),
274	    }
275	}
