148	    ensure!(
149	        qk_rope_head_dim == KIMI_K2_QK_ROPE_HEAD_DIM,
150	        "qk_rope_head_dim mismatch: {qk_rope_head_dim}"
151	    );
152	    ensure!(
153	        v_head_dim == KIMI_K2_V_HEAD_DIM,
154	        "v_head_dim mismatch: {v_head_dim}"
155	    );
156	    ensure!(
157	        n_routed_experts == KIMI_K2_ROUTED_EXPERTS,
158	        "n_routed_experts mismatch: {n_routed_experts}"
159	    );
160	    ensure!(
161	        num_experts_per_tok == KIMI_K2_TOPK,
162	        "num_experts_per_tok mismatch: {num_experts_per_tok}"
163	    );
164	    ensure!(
165	        n_shared_experts == KIMI_K2_SHARED_EXPERTS,
166	        "n_shared_experts mismatch: {n_shared_experts}"
167	    );
168	    ensure!(
169	        moe_intermediate_size == KIMI_K2_EXPERT_INTERMEDIATE,
170	        "moe_intermediate_size mismatch: {moe_intermediate_size}"
171	    );
172	    ensure!(
173	        dense_intermediate_size == KIMI_K2_DENSE_INTERMEDIATE,
174	        "intermediate_size mismatch: {dense_intermediate_size}"
175	    );
176	    ensure!(
177	        (rms_norm_eps - f64::from(KIMI_K2_RMS_NORM_EPS)).abs() < 1.0e-12,
178	        "rms_norm_eps mismatch: {rms_norm_eps}"
179	    );
180	
181	    let rope_scaling = text
182	        .get("rope_scaling")
183	        .ok_or_else(|| anyhow::anyhow!("Kimi config missing rope_scaling"))?;
184	    let rope_scaling_type = rope_scaling
185	        .get("type")
186	        .and_then(Value::as_str)
187	        .map(ToOwned::to_owned);
188	    ensure!(
189	        rope_scaling_type.as_deref() == Some("yarn"),
190	        "Kimi rope_scaling.type must be yarn, got {:?}",
191	        rope_scaling_type
192	    );
193	    ensure_float_close(
194	        number_field(rope_scaling, "factor")?,
195	        f64::from(KIMI_K2_YARN_FACTOR),
196	        1.0e-6,
197	        "rope_scaling.factor",
198	    )?;
199	    ensure!(
200	        usize_field(rope_scaling, "original_max_position_embeddings")?
201	            == KIMI_K2_YARN_ORIGINAL_MAX_POS,
202	        "Kimi rope_scaling.original_max_position_embeddings mismatch"
203	    );
204	    ensure_float_close(
205	        number_field(rope_scaling, "beta_fast")?,
206	        f64::from(KIMI_K2_YARN_BETA_FAST),
207	        1.0e-6,
208	        "rope_scaling.beta_fast",
209	    )?;
210	    ensure_float_close(
211	        number_field(rope_scaling, "beta_slow")?,
212	        f64::from(KIMI_K2_YARN_BETA_SLOW),
213	        1.0e-6,
214	        "rope_scaling.beta_slow",
215	    )?;
216	    ensure_float_close(
217	        number_field(rope_scaling, "mscale")?,
218	        1.0,
219	        1.0e-12,
220	        "rope_scaling.mscale",
221	    )?;
222	    ensure_float_close(
223	        number_field(rope_scaling, "mscale_all_dim")?,
224	        1.0,
225	        1.0e-12,
226	        "rope_scaling.mscale_all_dim",
227	    )?;
228	
229	    let quantization_config = text.get("quantization_config");
230	    let quant_method = quantization_config
231	        .and_then(|value| value.get("quant_method"))
232	        .and_then(Value::as_str)
233	        .map(ToOwned::to_owned);
234	    let quant_format = quantization_config
235	        .and_then(|value| value.get("format"))
236	        .and_then(Value::as_str)
237	        .map(ToOwned::to_owned);
238	    ensure!(
239	        quant_method.as_deref() == Some("compressed-tensors"),
240	        "Kimi quantization_config.quant_method must be compressed-tensors, got {:?}",
241	        quant_method
242	    );
243	    ensure!(
244	        quant_format.as_deref() == Some("pack-quantized"),
245	        "Kimi quantization_config.format must be pack-quantized, got {:?}",
246	        quant_format
247	    );
248	
249	    Ok(())
250	}
