288	pub(crate) struct KimiK2ParallelShape {
289	    pub(crate) tp_world: usize,
290	    pub(crate) dp_world: usize,
291	    pub(crate) ep_world: usize,
292	    pub(crate) heads_per_tp: usize,
293	    pub(crate) local_experts: usize,
294	    pub(crate) vocab_per_tp: usize,
295	}
