297	/// TP-local tensor dimensions derived from `KimiK2ParallelShape`.
298	/// All fields scale with `heads_per_tp` or `tp_world`.
299	#[derive(Clone, Copy, Debug)]
300	pub(crate) struct KimiLocalDims {
301	    pub(crate) local_heads: usize,
302	    pub(crate) q_proj_out: usize,
303	    pub(crate) o_proj_in: usize,
304	    pub(crate) q_nope_out: usize,
305	    pub(crate) q_pe_out: usize,
306	    pub(crate) abs_q_out: usize,
307	    pub(crate) dense_gate_up: usize,
308	    pub(crate) dense_activated: usize,
309	    pub(crate) shared_gate_up: usize,
310	    pub(crate) shared_activated: usize,
311	}
