313	impl KimiK2ParallelShape {
314	    #[must_use]
315	    pub(crate) fn tp8_ep8() -> Self {
316	        Self::new(8, 1)
317	    }
318	
319	    #[must_use]
320	    pub(crate) fn tp1_dp8() -> Self {
321	        Self::new(1, 8)
322	    }
323	
324	    #[must_use]
325	    fn new(tp_world: usize, dp_world: usize) -> Self {
326	        let ep_world = tp_world * dp_world;
327	        Self {
328	            tp_world,
329	            dp_world,
330	            ep_world,
331	            heads_per_tp: KIMI_K2_HEADS / tp_world,
332	            local_experts: KIMI_K2_ROUTED_EXPERTS / ep_world,
333	            vocab_per_tp: KIMI_K2_VOCAB / tp_world,
334	        }
335	    }
336	
337	    #[must_use]
338	    pub(crate) fn local_dims(&self) -> KimiLocalDims {
339	        let h = self.heads_per_tp;
340	        KimiLocalDims {
341	            local_heads: h,
342	            q_proj_out: h * KIMI_K2_Q_HEAD_DIM,
343	            o_proj_in: h * KIMI_K2_V_HEAD_DIM,
344	            q_nope_out: h * KIMI_K2_QK_NOPE_HEAD_DIM,
345	            q_pe_out: h * KIMI_K2_QK_ROPE_HEAD_DIM,
346	            abs_q_out: h * KIMI_K2_KV_LORA_RANK,
347	            dense_gate_up: 2 * KIMI_K2_DENSE_INTERMEDIATE / self.tp_world,
348	            dense_activated: KIMI_K2_DENSE_INTERMEDIATE / self.tp_world,
349	            shared_gate_up: 2 * KIMI_K2_EXPERT_INTERMEDIATE / self.tp_world,
350	            shared_activated: KIMI_K2_EXPERT_INTERMEDIATE / self.tp_world,
351	        }
352	    }
353	
354	    #[must_use]
355	    pub(crate) fn parallel_config(&self) -> pegainfer_frontend::parallel::ParallelConfig {
356	        pegainfer_frontend::parallel::ParallelConfig::new(self.tp_world, self.dp_world)
357	    }
358	}
