223	fn tiny_manifest() -> KimiK2WeightManifest {
224	    let mut layers = Vec::new();
225	    for layer_idx in 0..KIMI_K2_LAYERS {
226	        let attention = KimiAttentionManifest {
227	            input_layernorm: fake(layer_idx, "input_layernorm.weight"),
228	            q_a_proj: fake(layer_idx, "self_attn.q_a_proj.weight"),
229	            q_a_layernorm: fake(layer_idx, "self_attn.q_a_layernorm.weight"),
230	            q_b_proj: fake(layer_idx, "self_attn.q_b_proj.weight"),
231	            kv_a_proj_with_mqa: fake(layer_idx, "self_attn.kv_a_proj_with_mqa.weight"),
232	            kv_a_layernorm: fake(layer_idx, "self_attn.kv_a_layernorm.weight"),
233	            kv_b_proj: fake(layer_idx, "self_attn.kv_b_proj.weight"),
234	            o_proj: fake(layer_idx, "self_attn.o_proj.weight"),
235	            post_attention_layernorm: fake(layer_idx, "post_attention_layernorm.weight"),
236	        };
237	        let kind = if layer_idx == 0 {
238	            KimiLayerKindManifest::Dense(KimiDenseMlpManifest {
239	                gate_proj: fake(layer_idx, "mlp.gate_proj.weight"),
240	                up_proj: fake(layer_idx, "mlp.up_proj.weight"),
241	                down_proj: fake(layer_idx, "mlp.down_proj.weight"),
242	            })
243	        } else {
244	            KimiLayerKindManifest::Moe(KimiMoeLayerManifest {
245	                router: KimiRouterManifest {
246	                    gate_weight: fake(layer_idx, "mlp.gate.weight"),
247	                    e_score_correction_bias: fake(layer_idx, "mlp.gate.e_score_correction_bias"),
248	                },
249	                shared_experts: KimiSharedExpertManifest {
250	                    gate_proj: fake(layer_idx, "mlp.shared_experts.gate_proj.weight"),
251	                    up_proj: fake(layer_idx, "mlp.shared_experts.up_proj.weight"),
252	                    down_proj: fake(layer_idx, "mlp.shared_experts.down_proj.weight"),
253	                },
254	                routed_experts: (0..KIMI_K2_ROUTED_EXPERTS)
255	                    .map(|expert_idx| KimiRoutedExpertManifest {
256	                        expert_idx,
257	                        gate_proj: fake_int4(layer_idx, expert_idx, "gate_proj"),
258	                        up_proj: fake_int4(layer_idx, expert_idx, "up_proj"),
259	                        down_proj: fake_int4(layer_idx, expert_idx, "down_proj"),
260	                    })
261	                    .collect(),
262	            })
263	        };
264	        layers.push(KimiLayerManifest {
265	            layer_idx,
266	            attention,
267	            kind,
268	        });
269	    }
270	    KimiK2WeightManifest {
271	        text_tensor_count: 208_215,
272	        token_embedding: top("language_model.model.embed_tokens.weight"),
273	        final_norm: top("language_model.model.norm.weight"),
274	        lm_head: top("language_model.lm_head.weight"),
275	        layers,
276	        parallel: KimiK2ParallelShape::tp8_ep8(),
277	    }
278	}
