fn text_tensor_names() -> Vec<String> {
    let mut names = vec![
        "language_model.model.embed_tokens.weight".to_owned(),
        "language_model.model.norm.weight".to_owned(),
        "language_model.lm_head.weight".to_owned(),
    ];
    for layer in 0..KIMI_K2_LAYERS {
        let attn = [
            "input_layernorm.weight",
            "self_attn.q_a_proj.weight",
            "self_attn.q_a_layernorm.weight",
            "self_attn.q_b_proj.weight",
            "self_attn.kv_a_proj_with_mqa.weight",
            "self_attn.kv_a_layernorm.weight",
            "self_attn.kv_b_proj.weight",
            "self_attn.o_proj.weight",
            "post_attention_layernorm.weight",
        ];
        names.extend(attn.iter().map(|s| format!("language_model.model.layers.{layer}.{s}")));
        if layer < KIMI_K2_DENSE_LAYERS {
            for s in ["mlp.gate_proj.weight", "mlp.up_proj.weight", "mlp.down_proj.weight"] {
                names.push(format!("language_model.model.layers.{layer}.{s}"));
            }
        } else {
            names.push(format!("language_model.model.layers.{layer}.mlp.gate.weight"));
            names.push(format!("language_model.model.layers.{layer}.mlp.gate.e_score_correction_bias"));
            for s in ["mlp.shared_experts.gate_proj.weight", "mlp.shared_experts.up_proj.weight", "mlp.shared_experts.down_proj.weight"] {
                names.push(format!("language_model.model.layers.{layer}.{s}"));
            }
            for expert in 0..KIMI_K2_ROUTED_EXPERTS {
                for proj in ["gate_proj", "up_proj", "down_proj"] {
                    names.push(format!("language_model.model.layers.{layer}.mlp.experts.{expert}.{proj}.weight_packed"));
                    names.push(format!("language_model.model.layers.{layer}.mlp.experts.{expert}.{proj}.weight_scale"));
                }
            }
        }
    }
    names
}

